using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Web.Script.Serialization;using ReplierDesktop;
public static class GroundedRescore {
 public sealed class Document {public Video video;public object before;public DualCommentResult after;public CommentSuggestion best;}
 public static int Main(string[] args){try{var json=new JavaScriptSerializer{MaxJsonLength=16*1024*1024};string path=Path.Combine(args[0],"extension/data/replier-grounded-checks/whole-comment-before-after-CFYOk550ckc.json");var doc=json.Deserialize<Document>(File.ReadAllText(path));var content=new ContentStore(Path.Combine(args[0],"extension/data/replier/content")).Load(doc.video.Id);var rows=doc.after.Batches.Where(b=>b.Result!=null).SelectMany(b=>b.Result.Comments).ToArray();foreach(var r in rows)r.FitContextKey=null;
 var models=DualCommentService.Models.ToDictionary(n=>n,n=>new LocalModel(Path.Combine(args[0],"extension/.runtime/replier-llm"),n));try{var scoring=new CombinedFitScoring(new FitScoring(models[DualCommentService.Models[0]]),new FitScoring(models[DualCommentService.Models[1]]),models[DualCommentService.Models[0]].Unload);scoring.Evaluate(doc.video,content,rows,CancellationToken.None).GetAwaiter().GetResult();models[DualCommentService.Models[1]].Unload().GetAwaiter().GetResult();new SceneTieBreaker((n,b,t)=>models[n].Chat(b,t),n=>models[n].Unload()).Apply(doc.video,rows,CancellationToken.None).GetAwaiter().GetResult();}finally{foreach(var m in models.Values.Reverse())m.Dispose();}
 doc.best=rows.Where(r=>r.FitEligible==true).OrderByDescending(r=>r.FitScore).ThenByDescending(r=>r.TiePreference).FirstOrDefault();foreach(var r in rows)Console.WriteLine(r.FitScore+" | "+r.Text);Console.WriteLine("BEST "+(doc.best==null?"NONE":doc.best.Text));File.WriteAllText(Path.Combine(args[0],"extension/data/replier-grounded-checks/whole-comment-final-CFYOk550ckc.json"),json.Serialize(new{video=doc.video,before=doc.before,after=doc.after,best=doc.best,same_generated_candidates=true}));return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
